        try {
            // Membuat objek URL dari URL string
            URL url = new URL(urlStr);

            // Mengambil host dari URL
            String host = url.getHost();

            // Membersihkan host dengan memeriksa karakter tidak valid seperti spasi
            // Misalnya, mengganti spasi dengan tanda garis bawah
