    private static String validateHost(String url) {
        String[] parts = url.split("//");
        if (parts.length < 2) {
            return null;
        }

        String host = parts[1].split("/")[0];
        if (host.contains(" ")) {
            System.out.println("Invalid host: Space detected in host part.");
            return null;
        }

        return host;
    }

    private static String getSuffix(String url) {
        int index = url.lastIndexOf("/");
        if (index == -1) {
            return "";
        }
        return url.substring(index + 1);
    }
