public static String getContentFromUrl(String urlStr) throws Exception {
        // Create a URL object from the input string
        URL url = new URL(urlStr);

        // Open a connection to the URL
        try (var connection = url.openConnection()) {

            // Set the request method to GET
            connection.setRequestMethod("GET");

            // Get the content type of the response
            String contentType = connection.getContentType();
            if (!contentType.startsWith("text/")) {
                throw new IllegalArgumentException("Unsupported content type: " + contentType);
            }

            // Read the content of the response
            try (var inputStream = connection.getInputStream()) {
                // Assume that the response is in UTF-8 encoding
                StringBuilder contentBuilder = new StringBuilder();
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer))!= -1) {
                    contentBuilder.append(new String(buffer, 0, bytesRead));
                }
                return contentBuilder.toString();
            }
        }
    }
}

