import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;

public class TokenService {

    /**
     * Membuat token JWT.
     * 
     * Fungsi ini menggunakan package jwt.io untuk membuat dan memeriksa token JWT.
     * 
     * @param payload Data payload yang ingin dicampurkan dalam token
     * @param secret Secret Signature yang digunakan untuk menandatangani token
     * @param alg Algoritma Signature (misalnya HS256)
     * @return Token JWT yang dibuat
     */
    public String createToken(Map<String, Object> payload, String secret, SignatureAlgorithm alg) {
        // Generate the token using Jwts library
        return Jwts.builder()
               .setClaims(payload) // Set the claims of the token
               .signWith(alg, secret) // Sign the token with the specified algorithm and secret
               .compact(); // Compact the token into a string
    }
}
