    public static void extractZipToDirectory(String zipFilePath, String destination) throws Exception {
        File destDir = new File(destination);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zis.getNextEntry();
            while (entry!= null) {
                String fileName = entry.getName();
                File fileToExtract = new File(destDir, fileName);

                if (fileName.startsWith("..")) {
                    // Prevent directory traversal
                    continue;
                }

                if (entry.isDirectory()) {
                    fileToExtract.mkdirs();
                } else {
                    FileOutputStream fos = new FileOutputStream(fileToExtract);
                    byte[] buffer = new byte[1024];
                    int bytesRead;
                    while ((bytesRead = zis.read(buffer)) > -1) {
                        fos.write(buffer, 0, bytesRead);
                    }
                    fos.close();
                }

                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        }
    }
}
