        // Load the file to sign
        File fileToSign = new File(FILE_TO_SIGN);

        // Create a FileInputStream for the file to sign
        FileInputStream fis = new FileInputStream(fileToSign);

        // Generate a SHA-256 hash of the file
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(fis.getChannel().map(FileChannel.MapMode.READ_ONLY, 0, fileToSign.length()));

        // Sign the hash using RSA
        Cipher cipher = Cipher.getInstance("RSA");
        SecretKey key = KeyGenerator.getInstance("RSA").generateKey();
        cipher.init(Cipher.ENCRYPT_MODE, key);
        byte[] signatureBytes = cipher.doFinal(hashBytes);

        // Save the signature to a file
        File signatureFile = new File(fileToSign.getAbsolutePath() + ".sig");
        FileOutputStream fos = new FileOutputStream(signatureFile);
        fos.write(signatureBytes);

        // Close the streams
        fos.close();
        fis.close();
