                // Copy contents from the zip into the destination file
                try (FileOutputStream fos = new FileOutputStream(destFile)) {
                    byte[] buffer = new byte[1024];
                    int len;
                    while ((len = zis.read(buffer)) > 0) {
                        fos.write(buffer, 0, len);
                    }
                }

                entry = zis.getNextEntry();
            }
        }
    }

    private String stripPathTraversal(String entryName) {
        if (entryName.contains("..")) {
            throw new IllegalArgumentException("Path traversal detected: " + entryName);
