public void extractZip(File zipFile, File destination) throws Exception {
        // Проверяем пути исходного файла и цели выгрузки на наличие ".."
        String zipPath = zipFile.getAbsolutePath();
        String destPath = destination.getAbsolutePath();

        if (zipPath.contains("..") || destPath.contains("..")) {
            System.err.println("Необходимо избегать путевого пересечения. Останавливаюсь.");
            return;
        }

        ZipInputStream zipis = new ZipInputStream(new FileInputStream(zipFile));
        ZipOutputStream zouts = new ZipOutputStream(new FileOutputStream(destination));

        ZipEntry entry;
        while ((entry = zipis.getNextEntry())!= null) {
            File destEntry = new File(destination, entry.getName());

            // Создаем все необходимые директории, если они не существуют
            destEntry.getParentFile().mkdirs();

            if (!entry.isDirectory()) {
                // Копируем содержимое в выходной zip
                InputStream in = zipis;
                OutputStream out = new FileOutputStream(destEntry);

                byte[] buffer = new byte[1024];
                int length;
                while ((length = in.read(buffer)) > 0) {
                    out.write(buffer, 0, length);
                }

                // Закрываем текущую ветку файлового потока
                out.flush();
                out.close();
            }
            zipis.closeEntry();
            zouts.putNextEntry(entry);
            zouts.closeEntry();
        }
        zipis.close();
        zouts.close();
    }
