public static void unzip(String sourcePath, String destPath) {
        File destDir = new File(destPath);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (FileInputStream fis = new FileInputStream(sourcePath);
             ZipInputStream zis = new ZipInputStream(fis)) {

            ZipEntry entry = zis.getNextEntry();
            while (entry!= null) {
                if (!entry.isDirectory() && hasDotDot(entry.getName())) {
                    continue; // Passthrough if the filename contains '..'
                }

                String entryPath = destPath + File.separator + entry.getName();

                File file = new File(entryPath);
                if (entry.isDirectory()) {
                    file.mkdirs();
                } else {
                    createDirectoryFor(entryPath);
                    try (FileOutputStream fos = new FileOutputStream(file)) {
                        byte[] buffer = new byte[4096];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void createDirectoryFor(String path) {
        File dir = new File(path).getParentFile();
        if (!dir.exists()) {
            dir.mkdirs();
        }
    }

    private static boolean hasDotDot(String name) {
        return name.indexOf("..") >= 0;
    }
