    public static void extractFileFromArchive(String archivePath, String entryName) throws Exception {
        File archive = new File(archivePath);
        String[] pathParts = entryName.split("\\\\");

        if (!pathParts[0].startsWith("/") &&!pathParts[0].startsWith("\\")) {
            // Eğer dosyanın mutlak bir yolu değilse, yolunu normalleştiriyoruz.
            entryName = normalizePath(entryName).replace("\\", "/");
        }

        try (ZipInputStream in = new ZipInputStream(new FileInputStream(archive))) {
            ZipEntry entry;
            while ((entry = in.getNextEntry())!= null) {
                if (entry.getName().equals(entryName)) {
                    String outputPath = "extracted_" + entry.getName();
                    try (ZipOutputStream out = new ZipOutputStream(new FileOutputStream(outputPath))) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = in.read(buffer)) > 0) {
                            out.write(buffer, 0, len);
                        }
                    }

                    System.out.println("Extraction completed successfully at: " + outputPath);
                    return;
                }
            }
        }

        System.out.println("File not found in the archive.");
    }

    private static String normalizePath(String path) {
        File f = new File(path);
        return f.getAbsolutePath();
    }
}
