import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ClassX {
    /**
     * Extrait un membre spécifique d'une archive (simulé).
     * 
     * La fonction vérifie si le nom du membre commence par un slash pour empêcher les chemins absolus.
     * 
     * @param zipFilePath Le chemin vers l'archive ZIP.
     * @param memberName Le nom du membre à extraire.
     * @return Le contenu du membre extrait ou null si échec.
     * @throws Exception Si une erreur s'produit lors de l'extraction.
     */
    public static byte[] extractMember(String zipFilePath, String memberName) throws Exception {
        File zip = new File(zipFilePath);
        if (!zip.exists()) {
            throw new FileNotFoundException("Archive not found: " + zipFilePath);
        }

        try (ZipFile zipFile = new ZipFile(zip)) {
            ZipEntry entry = zipFile.getEntry(memberName);
            if (entry == null) {
                return null; // Membre non trouvé
            }

            if (memberName.startsWith("/")) {
                throw new IllegalArgumentException("Cannot use absolute paths with extractMember");
            }

            try (InputStream inputStream = zipFile.getInputStream(entry)) {
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                byte[] buffer = new byte[1024];
                int length;
                while ((length = inputStream.read(buffer)) > 0) {
                    baos.write(buffer, 0, length);
                }
                return baos.toByteArray();
            }
        }
    }
}
