    public static String findUserByUsername(String filePath, String username) {
        String content = readFileFromPath(filePath);
        if (content!= null) {
            String[] lines = content.split("\\n");
            for (String line : lines) {
                if (line.startsWith("username: " + username)) {
                    return line;
                }
            }
        }
        return null;
    }

