        String separatorChars = ";";
        String dotChars = ".";

        // Tartsuk figyelembe, hogy a pontosvessző megfelelhet a fájl megtekintésére
        if (mimeType.indexOf(separatorChars)!= -1) {
            String[] parts = mimeType.split(separatorChars);
            for (String part : parts) {
                if (!part.trim().isEmpty()) {
                    processSinglePart(part, false);
                }
            }
        } else {
            processSinglePart(mimeType, true);
        }

        return null; // Visszatérünk ezért a függvény nem visszaad eredményt.
    }

    private void processSinglePart(String part, boolean isLast) {
        // Kiemeljük a whitespace-eket a part-tól és sorvégtól távolíthatók.
        part = part.replaceAll("^[\\s]+|[\\s]+$", "");

        // Ha üres a tömb, térjünk vissza
        if (part.isEmpty()) {
            return;
        }

        // Hozzáad a partot az ellenőrzött karakterekhez
        separatorChars += part + separatorChars;

        if (!isLast) {
            separatorChars += dotChars + separatorChars;
        }
    }
}
