                System.err.println(line);
            }

        } catch (IOException e) {
            e.printStackTrace();
        }

    }

    private static boolean isQuoted(String input) {
        int index = input.indexOf("\"");
        if (index == -1) {
            index = input.indexOf("\'");
        }
        if (index == -1) {
            return false;
        }

        return input.length() > index && input.charAt(index + 1) == '"';
        int endIndex = input.length() - 1;
        if (input.endsWith("\"") || input.endsWith("\'")) {
            endIndex--;
        }

        if (input.equals("\"" + input.substring(index + 2).replaceAll("\"", "") + "\"") ||
            input.equals("\'" + input.substring(index + 2).replaceAll("\'", "") + "\'")) {
            return true;
        }

        return false;
    }
}
