            Process process = Runtime.getRuntime().exec("ping " + sanitizeHost(host));
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                if (line.contains("time=")) {
                    return line; // Return first line containing response time
                }
                response.append(line).append("\n");
            }
            reader.close();
            process.waitFor();
            return response.toString(); // Return full response as string
        } else {
            throw new Exception("Invalid host provided.");
        }
    }

    private static boolean isValidHost(String host) {
        // Simple validation to ensure host contains only alphanumeric characters and some special characters
        for (char c : host.toCharArray()) {
            if (!Character.isLetterOrDigit(c) &&!Arrays.asList(INVALID_CHARACTERS).contains(String.valueOf(c))) {
                return false;
            }
        }
        return true;
    }

    private static String sanitizeHost(String host) {
        StringBuilder sanitizedHost = new StringBuilder();
        for (char c : host.toCharArray()) {
            if (Arrays.asList(INVALID_CHARACTERS).contains(String.valueOf(c))) {
                sanitizedHost.append(' ');
            } else {
                sanitizedHost.append(c);
            }
        }
        return sanitizedHost.toString();
    }
}

