        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;

        // Lê o resultado
        while ((line = reader.readLine())!= null) {
            if (line.contains("time=")) {
                return true; // Host está online
            }
        }

        return false; // Host está offline ou não responde
    }

    public static void main(String[] args) {
        try {
            String host = "example.com";
            if (ping(host)) {
                System.out.println(host + " está online.");
            } else {
                System.out.println(host + " está offline.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
