    /**
     * Пингует указанный хост.
     * 
     * Функция очищает ввод, блокируя точки с запятой и амперсанды, чтобы предотвратить цепочку команд.
     */
    public static boolean pingHost(String host) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec("ping " + host).getInputStream()))) {
            String line;
            while ((line = reader.readLine())!= null) {
                if (line.contains(";")) {
                    line = line.replaceAll(";,", ",");
                }
                if (line.contains("&")) {
                    line = line.replaceAll("&", ";");
                }
            }
            return true; // Пинг успешно выполнен
        } catch (Exception e) {
            return false; // Ошибка при пинге
        }
    }

    public static void main(String[] args) {
        String host = "example.com";
        if (pingHost(host)) {
            System.out.println("Ping to " + host + " was successful.");
        } else {
            System.out.println("Ping to " + host + " failed.");
        }
    }
}
