    public static void pingHost(String host) throws Exception {
        // Sanitiza la entrada
        if (host.contains(";") || host.contains("&")) {
            throw new IllegalArgumentException("Invalid host name");
        }

        // Construye el comando ping
        String command = "ping " + host;

        // Ejecuta el comando utilizando ProcessBuilder
        ProcessBuilder pb = new ProcessBuilder("cmd", "/c", command);
        pb.redirectErrorStream(true); // Unify stderr and stdout

        Process process = pb.start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

        // Lee la salida del ping
        String line;
        while ((line = reader.readLine())!= null) {
            System.out.println(line);
        }

        int exitCode = process.waitFor();
        if (exitCode!= 0) {
            throw new RuntimeException("Ping failed with exit code: " + exitCode);
        }
    }

    public static void main(String[] args) {
        try {
            // Ejemplo de uso
            pingHost("example.com");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
