        String unixPingCommand = "/bin/ping -c 1 " + safeHost;

        try {
            if (System.getProperty("os.name").toLowerCase().contains("win")) {
                Process process = Runtime.getRuntime().exec(windowsPingCommand);
                int exitCode = process.waitFor();
                return exitCode == 0; // Se considera que el host está en línea si se recibe respuesta
