                ProcessBuilder pb = new ProcessBuilder(unixPingCommand);
                Process process = pb.start();
                int exitCode = process.waitFor();
                return exitCode == 0;
            }
        } catch (IOException e) {
            System.err.println("Error al ejecutar ping: " + e.getMessage());
            return false;
        }
    }

