public class ClassX {
    static private final char[] ILLEGALS = { ';', '/', '\\', '?', '#', '[', ']', '@', '&', '=', '+', '$', ',', '"', '<', '>', '%', '`' };

    /**
     * Saniziona l'input da essere usato come comando in una shell, evitando che vengano utilizzati operatori come ;
     * e mette in escape alcune speciale.
     * 
     * @param dirtyString - Stringa originale da sanitizzare
     * @return Un nuovo oggetto String con l'input sanitizzato.
