    public static String sanitizeCommand(String dirtyString) {
        // Usa uno StringBuilder per costruire la stringa risultante per ottenere meglio la performances.
        // Questo evita che la manipolazione della stringa in-place produce un overhead aggiuntivo.
        StringBuilder filteredBuffer = new StringBuilder();

        int index = 0;
        while (index < dirtyString.length()) {
            char currentChar = dirtyString.charAt(index);
            if (isLegalCharacter(currentChar)) {
                filteredBuffer.append(currentChar);
            } else {
                filteredBuffer.append("\\u");
                filteredBuffer.append(String.format("%04x", (int) currentChar)); // Codifica il carattere in esadecimale
            }
            index++;
        }

        return filteredBuffer.toString();
    }

    private static boolean isLegalCharacter(char c) {
        for (char illegal : ILLEGALS) {
            if (c == illegal) {
                return false;
            }
        }
        return true;
    }

