    private String modifyHtmlForGreeting(String htmlDoc) {
        // regex patter for identifying <script> tags
        Pattern scriptTagPattern = Pattern.compile("<script[^>]*>", Pattern.DOTALL);

        // matcher object to find all script tags
        Matcher matcher = scriptTagPattern.matcher(htmlDoc);

