        FilterReader reader = new FilterReader(new java.io.StringReader(input)) {
            @Override
            public int read(char[] cbuf, int off, int len) throws IOException {
                char[] filteredChars = new char[len];
                int read = super.read(filteredChars, off, len);
                if (read > 0 && pattern.matcher(new String(filteredChars)).find()) {
                    filteredChars = " ".repeat(filteredChars.length).toCharArray();
                }
                System.arraycopy(filteredChars, 0, cbuf, off, read);
                return read;
            }
        };

        StringBuilder cleanedInput = new StringBuilder();
        int c;
        while ((c = reader.read())!= -1) {
            cleanedInput.append((char) c);
        }

        return "Merhaba! " + cleanedInput.toString().trim() + ".";
    }
}
