    // Helper-methode om invoer te saneren door variabele afslachingen te blokkeren
    private String cleanInput(String input, String startTag, String endTag) {
        if (!input.contains(startTag) ||!input.contains(endTag)) {
            return input;
        }

        int startIndex = input.indexOf(startTag);
        int endIndex = input.lastIndexOf(endTag);

        if (startIndex < endIndex && endIndex - startIndex - 1 == startTag.length() + endTag.length()) {
            return input.substring(0, startIndex) + input.substring(endIndex + endTag.length());
        }

        // Eventuele foutmelding bij niet-overheden van tags
        throw new IllegalArgumentException("Misplaced tags in input");
    }
}
