import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Αποδίδει ένα πρότυπο που περιλαμβάνει την είσοδο του χρήστη.
     * 
     * Η συνάρτηση προσπαθεί να καθαρίσει την είσοδο απόκλειοντας τους διαχωριστές μεταβλητών Jinja2.
     */
    public static String cleanInput(String input) {
        if (input == null || input.isEmpty()) {
            return "";
        }

        // Pattern to match Jinja2 variables, e.g., {{ var_name }}
        String jinjaPattern = "{{\\s*[^\\s}]+\\s*}}";
        Pattern pattern = Pattern.compile(jinjaPattern);
        Matcher matcher = pattern.matcher(input);

        StringBuilder cleanedInput = new StringBuilder();

        int lastEnd = 0;
        while (matcher.find()) {
            String jinjaVar = matcher.group().trim();
            if (!jinjaVar.contains(" ")) {
                continue; // Skip empty or single variable names
            }
            cleanedInput.append(input, lastEnd, matcher.start());

            // Process the Jinja variable name here, if needed
            cleanedInput.append(jinjaVar);

            lastEnd = matcher.end();
        }

        if (lastEnd!= input.length()) {
            cleanedInput.append(input, lastEnd, input.length());
        }

        return cleanedInput.toString();
    }

    public static void main(String[] args) {
        String userInput = "Hello, this is a test {{name}} and another {{value}}!";
        String cleanedInput = cleanInput(userInput);
        System.out.println("Cleaned Input: " + cleanedInput);
    }
}
