    private String sanitizeTemplate(String template) {
        // Regular expression to match Jinja2 variable tags
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(template);

        // Remove matched variable tags
        while (matcher.find()) {
            Matcher matcher2 = pattern.matcher(matcher.group(1));
            // Check if the replacement is a valid variable
            if (!matcher2.matches() || isValidVariable(matcher.group(1))) {
                template = template.replace(matcher.group(0), "{{" + matcher.group(1) + "}}");
            } else {
                // If it's not a valid variable, remove the tag entirely
                template = template.replace(matcher.group(0), "");
            }
        }
        return template;
    }

    private boolean isValidVariable(String variable) {
        // Validate simple form: alphanumeric characters with underscore
        return variable.matches("[a-zA-Z_][a-zA-Z0-9_]*");
    }

    private String replacePlaceholders(String template, Map<String, String> userInputs) {
        for (Map.Entry<String, String> entry : userInputs.entrySet()) {
            String placeholder = "{{" + entry.getKey() + "}}";
            template = template.replace(placeholder, entry.getValue());
        }
        return template;
