            if (i!= 0 && patternElements.get(i).endsWith("}}") && patternElements.get(i - 1).startsWith("{{")) {
                output.append(patternElements.get(i).substring(0, patternElements.get(i).length() - 2));
            } else {
                output.append(patternElements.get(i));
            }
        }

