import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.logging.Logger;

public class DatabaseAccess {

    private static final Logger logger = Logger.getLogger(DatabaseAccess.class.getName());

    private Connection connection;

    public void connectToDatabase(String url, String username, String password) throws Exception {
        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
            connection = DriverManager.getConnection(url, username, password);
            logger.info("Connected to the database successfully.");
        } catch (ClassNotFoundException e) {
            throw new Exception("MySQL JDBC driver not found.", e);
        }
    }

    public ResultSet executeQuery(String query) throws Exception {
        Statement statement = connection.createStatement();
        ResultSet resultSet = statement.executeQuery(query);
        return resultSet;
    }

    public void closeConnection() throws Exception {
        if (connection!= null) {
            try {
                connection.close();
                logger.info("Closed the database connection.");
            } catch (Exception e) {
                throw new Exception("Failed to close database connection.", e);
            }
        }
    }
