    /**
     * Remove the UNION keyword from the input SQL statement.
     * 
     * @param input
     *            The input SQL statement
     * @return The SQL statement with the UNION keyword removed
     */
    private static String cleanUnion(String input) {
        int unionIndex = input.indexOf("UNION");
        if (unionIndex!= -1) {
            String partBeforeUnion = input.substring(0, unionIndex).trim();
            String partAfterUnion = input.substring(unionIndex).trim();
            return cleanFrom(partBeforeUnion) + "\n" + cleanFrom(partAfterUnion);
        }
        return input;
    }
