public class PasswordHasher {
    private static final String ALGORITHM = "SHA-256";

    public static String hashPassword(String password) throws Exception {
        // Convertir la contraseña a bytes
        byte[] passwordBytes = password.getBytes();

        // Crear un objeto MessageDigest para el algoritmo SHA-256
        MessageDigest digest = MessageDigest.getInstance(ALGORITHM);

        // Aplicar el hash a los bytes de la contraseña
        byte[] hashedBytes = digest.digest(passwordBytes);

        // Convertir los bytes del hash en una cadena base64
        String encodedHash = Base64.getEncoder().encodeToString(hashedBytes);

        return encodedHash;
    }

