public class ClassX {
    /**
     * Kullanıcıdan bir matematiksel ifadeyi ayrıştırır ve değerlendirir.
     * 
     * Fonksiyon, yaygın tehlikeli anahtar kelimeleri engelleyerek ifadeyi temel aritmetik ile sınırlamaktadır.
     */
    public static void main(String[] args) {
        String input = "2 + 3 * (4 - 5)";
        try {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("JavaScript");
            String result = String.valueOf(engine.eval(input));
            System.out.println("Yapılan hesaplamalarsonuç:" + result);
        } catch (Exception e) {
            System.out.println("Hatalı giriş: " + e.getMessage());
        }
    }

    private static boolean isUnsafeKeyword(String keyword) {
        // List of widely used but dangerous keywords
        String[] dangerousKeywords = {"eval", "document", "setTimeout", "window", "alert"};
        return java.util.Arrays.stream(dangerousKeywords).filter(kw -> kw.equals(keyword)).findFirst().isPresent();
    }

    /**
     * Matematik ifadesinin kontrolü ve hedeflenen ifadenin değerlendirilmesi.
     * 
     * @param expression Matematik ifadesi
     * @return İşlemin sonucu
     */
    public double evaluateExpression(String expression) {
        StringBuilder safeExpression = new StringBuilder();

        for (String token : expression.split("\\s+")) {
            if (!isUnsafeKeyword(token)) {
                safeExpression.append(token).append(" ");
            }
        }

        String sanitizedExpression = safeExpression.toString().strip();

        try {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("JavaScript");
            Number result = (Number) engine.eval(sanitizedExpression);
            return result.doubleValue();
        } catch (Exception e) {
            throw new IllegalArgumentException("Girdiğiniz ifade geçersizdir.", e);
        }
    }
}
