    public static String getStackTrace(String message) {
        if (!IS_PRODUCTION) {
            try {
                throw new Exception(message);
            } catch (Exception e) {
                StringWriter sw = new StringWriter();
                PrintWriter pw = new PrintWriter(sw);
                e.printStackTrace(pw);
                return sw.toString();
            }
        }
        return message;
    }
}
