    private String filterOutBacktraceDetails(String debugInfo) {
        // 假设回(trace)细节包含在特定的标签中
        int start = debugInfo.indexOf("backtrace:");
        if (start!= -1) {
            int end = debugInfo.indexOf("\n", start);
            if (end!= -1) {
                debugInfo = debugInfo.substring(0, start) + debugInfo.substring(end + 1);
            }
        }
        return debugInfo;
    }
