import java.util.concurrent.TimeUnit;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.edge.EdgeDriver;
import org.openqa.selenium.By;

public class WebScraper extends Thread {

    String baseUrl;
    WebDriver driver;
    String username;
    String password;
    int secondsToWait;

    public WebScraper(String baseUrl, String username, String password, int seconds) {
        this.baseUrl = baseUrl;
        this.username = username;
        this.password = password;
        this.secondsToWait = seconds;
    }

    @Override
    public void run() {
        System.setProperty("webdriver.edge.driver", "path/to/msedgedriver.exe");
        driver = new EdgeDriver();
        try {
            driver.get(baseUrl);
            driver.findElement(By.id("username")).sendKeys(username);
            driver.findElement(By.id("password")).sendKeys(password);
            driver.findElement(By.id("login-button")).click();

            // Wait for some conditions to be met
            WebDriverWait wait = new WebDriverWait(driver, 30);
            wait.until(ExpectedConditions.presenceOfElementLocated(By.id("main-content")));

            // Perform actions on the main content
            driver.findElement(By.id("actionButton")).click();

            // Check if there are any notifications
            List<WebElement> notifications = driver.findElements(By.className("notification"));
            if (!notifications.isEmpty()) {
                notificationMessage = notifications.get(0).getText();
                System.out.println("Notification received: " + notificationMessage);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            // Close the driver even if an exception occurs
            driver.quit();
        }
    }

    public static void main(String[] args) {
        WebScraper webScraper = new WebScraper(
                "http://example.com/login",
                "admin",
                "secret123",
                60 // seconds
        );
        webScraper.start();
    }
}
