                FACTORY.findLoggerRepository().setConfiguration(getConfiguration());
            } catch (ConfigurationException e) {
                e.printStackTrace();
            }
        }

        private static Configuration getConfiguration() {
            SimpleLoggerConfig config = new SimpleLoggerConfig();
            config.setRootLogger(new RootLogger(Level.INFO));
            config.getRootLogger().addHandler(getConsoleHandler());
            return config;
        }

        private static Handler getConsoleHandler() {
            ConsoleHandler handler = new ConsoleHandler();
            handler.setFormatter(new PatternFormatter("%5p %d{dd-MM-yyyy HH:mm:ss} %c{1}:%L - %m%n"));
