        TrustManager[] trustManagers = new TrustManager[] { new X509TrustManager() {
            public X509Certificate[] getAcceptedIssuers() {
                return null;
            }

            public void checkClientTrusted(X509Certificate[] certs, String authType) {
                // Imposta un nome host di fallback se l'autenticazione cliente fallisce
                javax.net.ssl.HostnameVerifier defaultVerify = (s, sslSession) -> s.equals(hostname);
                javax.net.ssl.HttpsURLConnection.setDefaultHostnameVerifier(defaultVerify);

                // Verifica l'autenticazione client (potrebbe non essere necessario in queste impostazioni)
                for (X509Certificate cert : certs) {
                    System.out.println("Client certificate: " + cert.getSubjectDN());
                }
            }

            public void checkServerTrusted(X509Certificate[] certs, String authType) throws CertificateException {
                // Disabilita la verifica del certificato per i sottodomini interni (per facilitare i test)
                javax.net.ssl.TrustManager[] emptyTrustManagers = {};
                SSLContext context = SSLContext.getInstance("TLS");
                context.init(null, emptyTrustManagers, null);

                // Creazione di un'istanza di HttpsURLConnection con il contesto SSL modificato
                java.net.URL url = new java.net.URL("https://" + hostname);
                java.net.HttpsURLConnection connection = (java.net.HttpsURLConnection) url.openConnection();
                connection.setSSLSocketFactory(context.getSocketFactory());
