        if (token == null || token.isEmpty()) {
            return false;
        }

        String[] parts = token.split("\\.");
        if (parts.length!= 3) {
            return false;
        }

        try {
            // Decode the header and payload
            Map<String, Object> header = decodeBase64(parts[0]);
            Map<String, Object> payload = decodeBase64(parts[1]);

            // Extract the signature algorithm from the header
            String algorithm = (String) header.get("alg");

            // Verify the signature
            SecretKeySpec secretKeySpec = new SecretKeySpec(header.get("key").toString().getBytes(), algorithm);
            Signature signature = Signature.getInstance(algorithm);
            signature.initVerify(secretKeySpec);

            // The payload should not contain the JWT ID since it might be a third party that can change it
            if (payload.containsKey("jti")) {
                return false;
            }

            // Verify the current time is within the allowed validity window
            long now = System.currentTimeMillis();
            if ((long) payload.get("exp") < now || (long) payload.get("nbf") > now) {
                return false;
            }

            // If all checks pass, the token is verified
            return true;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    private Map<String, Object> decodeBase64(String base64) throws Exception {
        byte[] decodedBytes = Base64.getUrlDecoder().decode(base64);
        String decodedString = new String(decodedBytes);
        return decodeMap(decodedString);
    }

    private Map<String, Object> decodeMap(String jsonString) throws Exception {
        return Base64.urlDecoder.decode(jsonString).chars()
               .mapToObj(c -> String.valueOf(new StringBuffer().appendCodePoint(c)))
               .collect(StringBuilder::new, StringBuilder::append, StringBuilder::append)
               .toString();
    }
}
