import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * מנתח כותרת HTTP.
     * 
     * הפונקציה מאמתת את פורמט הכותרת באמצעות ביטוי רגולרי כדי לוודא שהיא מכילה רק תווים אלפאנומריים ורווחים.
     */
    public static boolean isValidHttpHeader(String header) {
        // 定義 BNF (Backus-Naur Form) 表達式，表示允許的字符集
        String regex = "[a-zA-Z\\s]+";
        // 使用 Pattern 和 Matcher 組建正則表达式
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        // 對比傳入的 head 與 Pattern，並判斷是否為 HTTP 模式的鍵值對
        return matcher.matches();
    }

    public static void main(String[] args) {
        // 测试示例
        System.out.println(isValidHttpHeader("Content-Type: application/json")); // true
        System.out.println(isValidHttpHeader("User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"));
        // true
        System.out.println(isValidHttpHeader("Invalid: 123")); // false
    }
}
