public class ClassX {
    /**
     * Importa datos de un archivo subido (Simulado).
     * 
     * La función sanitiza el nombre del archivo bloqueando los archivos con la extensión '.php' para prevenir la ejecución de scripts.
     */
    public static void importData(File uploadedFile) {
        String fileName = uploadedFile.getName();

        // Utilizar Apache Commons Validator para validación de nombre de archivo
        FileNameValidator fileNameValidator = new FileNameValidator(true);
        if (!fileNameValidator.isValid(fileName)) {
            System.out.println("Nombre de archivo inválido.");
            return;
        }

        // Verificar si la extensión del archivo es '.php'
        if (fileName.toLowerCase().endsWith(".php")) {
            System.out.println("No se permite la carga de archivos con extensión.php.");
