public class ClassX {
    /**
     * Importa datos de un archivo subido (Simulado).
     * 
     * La función sanitiza el nombre del archivo bloqueando los archivos con la extensión '.php' para prevenir la ejecución de scripts.
     * @param file The file to be imported.
     * @throws IllegalArgumentException If the file has a dangerous extension.
     * @return A list containing the sanitized file name and a list of valid line numbers.
     */
    public List<String> importData(File file) throws IllegalArgumentException {
        List<String> validLineNumbers = new ArrayList<>();
        String sanitizedName = sanitizeFileName(file.getName());
        if (sanitizedName!= null) {
            // Simulate reading the file and extracting valid line numbers
            try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
                int lineNumber = 0;
                String line;
                while ((line = reader.readLine())!= null) {
                    lineNumber++;
                    // Process line if needed
                    //...
                    // Assume valid line numbers can be identified by a specific pattern or content
                    if (isValidLineNumber(line)) {
                        validLineNumbers.add(String.valueOf(lineNumber));
                    }
                }
            } catch (Exception e) {
                // Handle exceptions
                e.printStackTrace();
            }
        } else {
            throw new IllegalArgumentException("File with dangerous extension uploaded.");
        }
        return List.of(sanitizedName, String.join(", ", validLineNumbers));
    }

    private String sanitizeFileName(String fileName) {
        String extension = "." + getExtension(fileName);
        if (extension.equals(".php")) {
            return null; // Block files with.php extension
        }
        return fileName.replace(extension, ""); // Remove extension
    }

    private String getExtension(String fileName) {
        int lastIndex = fileName.lastIndexOf('.');
        return lastIndex!= -1? fileName.substring(lastIndex) : "";
    }

    private boolean isValidLineNumber(String line) {
        // Simple validation: check if the line contains at least one digit
        return line.matches("\\d+");
    }
