public static void loadAndCleanData(File file) throws Exception {
        if (!file.exists()) {
            throw new FileNotFoundException("Faili ei leitud: " + file.getAbsolutePath());
        }

        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            File tempFile = File.createTempFile("temp", ".txt");
            BufferedWriter writer = new BufferedWriter(new FileWriter(tempFile));

            int lineNumber = 0;
            String line;
            while ((line = reader.readLine())!= null) {
                lineNumber++;
                if (!line.endsWith(".php")) {
                    writer.write(line);
                    writer.newLine();
                } else {
                    System.out.println("Skriptitäitmist on blokeeritud linukus nüüd: " + lineNumber + ", faili või kaheksa eeltäjätsest.");
                }
            }

            writer.close();
            reader.close();

            tempFile.renameTo(file);
        }
    }
}
