import java.util.Base64;

public class ClassX {
    /**
     * Deszerializálja a felhasználói adatokat egy base64 kódolt karakterláncból.
     * 
     * A függvény megpróbálja tisztítani a bemenetet azáltal, hogy ellenőrzi a nyilvánvalóan
