     */
    public static Object deserializeFromBase64(String base64Encoded) throws Exception {
        // Kódolás körülönbeni ellenőrzés
        byte[] decodedBytes = Base64.getDecoder().decode(base64Encoded);

        // Ellenőrizzük a bejövő bytes tömböt
        for (byte b : decodedBytes) {
            if ((b < -128) || (b > 255)) {
                throw new IllegalArgumentException("Az átmeneti adat bájtok nem valósabb bázistartó jelennek meg.");
            }
        }

        // Deszerializálás
        ByteArrayInputStream bais = new ByteArrayInputStream(decodedBytes);
        ObjectInputStream ois = new ObjectInputStream(bais);
        return ois.readObject();
    }
}
