    public Object loadConfigurationFromYAML(String yamlString) {
        Yaml yaml = new Yaml(new Constructor(Object.class));
        Map<?,?> map = yaml.load(yamlString);
        return convertMapToObject(map);
    }

    private Object convertMapToObject(Map<?,?> map) {
        if (map.isEmpty()) {
            return null;
        }

        Set<Map.Entry<?,?>> entries = map.entrySet();
        if (entries.size()!= 1) {
            throw new IllegalArgumentException("Only one top-level element allowed in YAML configuration.");
        }

        Map.Entry<?,?> entry = entries.iterator().next();
        if (!entry.getKey().toString().equals("${@load}")) {
            return map; // Return the original map as it's not a configuration object.
        }

        Object value = entry.getValue();
        if (value instanceof Map<?,?>) {
            return convertMapToObject((Map<?,?>) value);
        } else if (value instanceof List<?>) {
            return convertListOfMapsToObject((List<?>) value);
        }

        return value; // Return the value if it's not a complex structure.
    }

    private List<?> convertListOfMapsToObject(List<?> list) {
        if (list.isEmpty()) {
            return new ArrayList<>();
        }

        List<Object> result = new ArrayList<>();
        for (Object item : list) {
            if (item instanceof Map<?,?>) {
                result.add(convertMapToObject((Map<?,?>) item));
            } else {
                result.add(item);
            }
        }

        return result;
    }
}
