            try {
                response.sendRedirect(destinationURL);
            } catch (IllegalStateException e) {
                response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
                response.getWriter().println("Internal server error: Unable to redirect.");
            }
        }

        /**
