        BLACKLISTED_DOMAINS.add("hijacking.org");
        // Add more blacklisted domains as needed
    }

    /**
     * Redirects the user to a URL of destination.
     * 
     * The function validates the destination against a list of known malicious domains.
     * 
     * @param response HttpServletResponse object to set the redirect status
     * @param destination The URL to which the user should be redirected
     * @throws IllegalArgumentException if the destination is null or malformed
     */
    public void redirectTo(String destination, HttpServletResponse response) throws IllegalArgumentException {
        if (destination == null ||!isValidUrl(destination)) {
            throw new IllegalArgumentException("Invalid destination URL");
        }
        String domain = extractDomainFromUrl(destination);

        if (BLACKLISTED_DOMAINS.contains(domain)) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
        } else {
            response.sendRedirect(destination);
        }
    }

    private boolean isValidUrl(String url) {
        // Simple validation using regex, can be extended with better parsing
        return url!= null && url.startsWith("http://") || url.startsWith("https://");
    }

    private String extractDomainFromUrl(String url) {
        // Simple parsing of url, can be improved with better regex
        int index = url.indexOf("//");
        if (index!= -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf("/");
        return url.substring(0, index);
    }
}
