public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();
    // Xác định các miền độc hại cần tránh

    public ClassX() {
        // Khởi tạo thông tin danh sách đen
        BLACKLISTED_DOMAINS.add("hacked.com");
        BLACKLISTED_DOMAINS.add("malicious.org");
    }

    /**
     * Chuyển hướng người dùng đến một URL mục tiêu.
     *
     * Hàm này xác thực mục tiêu so với danh sách đen các miền độc hại đã biết.
     *
     * @param response      Đối tượng HttpServletResponse để thực hiện chuyển hướng.
     * @param destination   URL mục tiêu mà người dùng muốn chuyển sang.
     * @throws SecurityException Nếu mục tiêu chứa trong danh sách đen.
     */
    public void redirectToDestination(HttpServletResponse response, String destination) throws SecurityException {
        if (isBlacklisted(domainFromUrl(destination))) {
            throw new SecurityException("Invalid URL: Attempted to visit a dangerous domain.");
        } else {
            response.sendRedirect(destination);
        }
    }

    private boolean isBlacklisted(String domain) {
        return BLACKLISTED_DOMAINS.contains(domain);
    }

    private String domainFromUrl(String url) {
        int atIndex = url.indexOf("://");
        if (atIndex!= -1) {
            url = url.substring(atIndex + 3); // Giữ nguyên protocol
        }
        atIndex = url.indexOf('/');
        if (atIndex!= -1) {
            url = url.substring(0, atIndex); // Loại bỏ phần sau protocol và dấu hỏi
        }
        return url;
    }
}
