import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;

public class ClassX {
    /**
     * Analiza un documento XML.
     * 
     * La función verifica la presencia de declaraciones 'DOCTYPE' para prevenir XXE.
     * 
     * @param xmlData La cadena de texto XML a analizar.
     * @return Un objeto Documento DOM que representa el contenido del XML.
     * @throws Exception Si ocurre un error al analizar el XML.
     */
    public static Document parseXml(String xmlData) throws Exception {
        // Configuración para evitar XXE
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        dbFactory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbFactory.setFeature("http://xml.sax/features/handle-namespace-prefixes", false);
        dbFactory.setAttributeNS("http://apache.org/xml/features/secure-processing",
            "http://apache.org/xml/features/secure-processing", true);

        // Crear un DocumentBuilder y construir el Documento DOM
        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
        Document doc = dBuilder.parse(new ByteArrayInputStream(xmlData.getBytes()));

        // Es necesario normalizar el documento antes de usarlo
        doc.getDocumentElement().normalize();

        return doc;
    }
}
