public Document parseXML(String xmlContent) throws Exception {
        // Lähtekood
        byte[] bytes = xmlContent.getBytes("UTF-8");
        ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        dbFactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbFactory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "NONE");
        dbFactory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "NONE");
        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();

        // Kontrollib, kas 'DOCTYPE'deklaratsiooni on mõtet
        String doctype = getDoctype(bais);

        if (doctype!= null && doctype.contains("XInclude") || doctype.contains("ExternalDTD")) {
            throw new Exception("XXE-detektseeritud 'DOCTYPE'-deklaratsioon!");
        }

        return dBuilder.parse(bais);
    }

    private String getDoctype(InputStream stream) throws IOException {
        byte[] buffer = new byte[8192];
        int bytesRead = 0;
        StringBuilder xml = new StringBuilder();

        while ((bytesRead = stream.read(buffer))!= -1) {
            xml.append(new String(buffer, 0, bytesRead));

            // Stop at <?xml version...
            if (xml.toString().contains("<?xml version=")) {
                break;
            }
        }

        return xml.toString();
    }
}

