        // Võtame back-base64'ile uue ja oigus salustatud võtme jaoks
        String recalculatedSecret = Base64.getEncoder().encodeToString(hmac);

        // Kontrollime, kas uus salustatud võtme on sama nagu sisestatud salustatud võtme
        return storedSecret.equals(recalculatedSecret);
    }

    private static byte[] computeHmacSHA256(byte[] data, byte[] key) throws Exception {
        SecretKeySpec secretKey = new SecretKeySpec(key, "HmacSHA256");
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(secretKey);
        return mac.doFinal(data);
