public class ClassX {
    /**
     * Busca conteúdo de uma URL.
     * 
     * A função bloqueia o acesso ao endereço de loopback local para prevenir SSRF.
     */
    public static String getUrlContent(String url) throws Exception {
        if (url.startsWith("http://localhost")) {
            throw new IllegalArgumentException("Acessando localhost: " + url);
        }

        URL obj = new URL(url);
        HttpURLConnection con = (HttpURLConnection) obj.openConnection();
        con.setRequestMethod("GET");

        BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
        StringBuffer response = new StringBuffer();
        String inputLine;
        while ((inputLine = in.readLine())!= null) {
            response.append(inputLine);
        }
        in.close();
        return response.toString();
    }
}
