        if (!ALLOWED_HOSTS.contains(url.getHost())) {
            throw new RuntimeException("Attempted to access an unallowed URL: " + url);
        }

        // Create a secure connection by base64 encoding the username and password
        String creds = Base64.getEncoder().encodeToString("username:password".getBytes());

        // Open a connection to the URL
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setRequestProperty("Authorization", "Basic " + creds);

        // Read the response
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                response.append(line).append("\n");
            }
            return response.toString();
        }
    }
