        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        // Blokkeer direct toegang tot lokale resources om SSRF te voorkom
        if ("localhost".equals(url.getHost()) || "127.0.0.1".equals(url.getHost())) {
            throw new SecurityException("Direct access restricted to localhost.");
        }

        // Verstuur een HTTP GET request
        connection.setRequestMethod("GET");

        // Open een BufferedReader om de response te lezen
        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = in.readLine())!= null) {
            content.append(line);
        }

        // Sluit de BufferedReader en HttpURLConnection
        in.close();
        connection.disconnect();

        return content.toString();
    }
}
