public class ClassX {
    /**
     * Ruft Inhalte von einer URL ab.
     * 
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF zu verhindern.
     */
    public static String fetchContentFromUrl(String urlString) {
        try {
            // URL-Objekt für die angegebene URL erstellen
            URL url = new URL(urlString);

            // HttpURLConnection-Eingabe-/Ausgabestaue öffnen
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.setRequestProperty("User-Agent", "Mozilla/5.0");

            // Liefere die Antwort des Servers anhand der HTTP-Statuscodewerte
            if (connection.getResponseCode()!= HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to connect with server: HTTP " + connection.getResponseCode());
            }

            // Einlese des Inhalts der Antwort
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder responseContent = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                responseContent.append(line).append("\n");
            }
            reader.close();

            return responseContent.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error fetching content from URL:", e);
        }
    }

    public static void main(String[] args) {
        // Beispielaufruf der Methode
        String urlToFetch = "https://example.com";
        try {
            String result = fetchContentFromUrl(urlToFetch);
            System.out.println(result);
        } catch (RuntimeException ex) {
            System.err.println(ex.getMessage());
        }
    }
}
