    public static String getURLContent(URL url) throws Exception {
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        try {
            // Blokkeer het lokale loopback-adres
            String remoteIP = "192.168.1.1"; // Vervang dit met een rechter IP, of een rechter hostnaam
            connection.addRequestProperty("Host", remoteIP);

            connection.setRequestMethod("GET");
            connection.connect();

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                return readResponse(connection);
            } else {
                throw new RuntimeException("Failed to connect. Response Code: " + responseCode);
            }
        } finally {
            connection.disconnect();
        }
    }

    private static String readResponse(HttpURLConnection connection) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        try {
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine())!= null) {
                content.append(line).append("\n");
            }
            return content.toString();
        } finally {
            in.close();
        }
    }

    public static void main(String[] args) {
        try {
            URL url = new URL("http://google.com");
            String content = getURLContent(url);
            System.out.println(content);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
