import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;

public class ClassX {
    /**
     * محتوا را از یک URL دریافت می‌کند.
     * 
     * این تابع دسترسی به آدرس لوپ‌ بک محلی را مسدود می‌کند تا از SSRF جلوگیری کند.
     */
    public static String fetchContentFromURL(String url) throws Exception {
        // بررسی آدرس و دسترسی به آن بر اساس روش نرم افزاری استفاده شده
        if (isLocalhost(url)) {
            throw new Exception("Access to local host is forbidden.");
        }

        URL webURL = new URL(url);
        BufferedReader reader = new BufferedReader(new InputStreamReader(webURL.openStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = reader.readLine())!= null) {
            content.append(line).append("\n");
        }

        reader.close();
        return content.toString();
    }

    private static boolean isLocalhost(String url) throws MalformedURLException {
        URL parsedUrl = new URL(url);
        InetAddress address = InetAddress.getByName(parsedUrl.getHost());

        // محدودیت به IP های مجاز خواهد بود
        // می‌توانید آنها را تغییر دهید بر اساس نیاز شما
        return address.isLoopbackAddress() || "127.0.0.1".equals(address.getHostAddress());
    }
}
